[97225] = {"Imagens de loas esquecidos", {"Colete 8 Imagens de Loas Esquecidos nas Ilhas do Eco. Leve-os para o Mestre Gadrin na Aldeia Sen'jin."}},
[97234] = {"Sala de leitura", {"Leve o material de leitura embrulhado à Biblioteca de Ventobravo."}},
[97236] = {"Presa de Gilthyiss", {"Entregue a Presa de Githyiss a alguém interessado no estudo de aranhas em Aldrassil."}},
[97237] = {"Direto da estante", {"Encontre todos os materiais de leitura espalhados pela biblioteca. Em seguida, fale novamente com Rui Lourenço no Parque de Ventobravo."}},
[97242] = {"A mistura de Yelmak", {"Pegue algumas folhas de Taboa e Gramalança que crescem em volta da água no Vale da Honra e fale novamente com Kor'geld na Alquimia e Poções do Yelmak."}},
[97243] = {"Clamor do fogo", {"Leve a Tocha da Chama Latente a Olariaan Queimabreve no Santuário das Chamas, nos Baixios dos Lufopomos."}},
[97244] = {"Clamor do fogo", {"Mate o Sacerdote do Céu Faladiel nos Baixios dos Lufopomos e colete o Coração de Faladiel."}},
[97245] = {"Clamor do fogo", {"Encontre o lar de Kuramaa no Planalto de Shen'dar e derrote o espírito em combate. Leve a Máscara de Kuramaa a Olariaan Queimabreve nos Baixios dos Lufopomos depois de vencer."}},
[97246] = {"A marmita do Migi", {"Visite a Fogueira de Borsgan e diga a ele que Thatog pediu para que você entregue o Almoço de Migi ao garoto pessoalmente."}},
[97249] = {"Comida preferida", {"Leve o Almoço de Migi para ele atrás do Castelo Grommash."}},
[97250] = {"Culpa errônea justamente corrigida", {"Mate soldados da Aliança que se aproximam dos Sertões na fronteira do Pântano Vadeoso e depois fale novamente com o Bruto Logmar no Acampamento Taurajo."}},
[97253] = {"Peças e pedaços", {"Colete 5 Punhados de Peças Complicadas do acampamento pirata superior, ao sul da Vila Catraca, e depois fale novamente com Wrenix, o Ignóbil, na Vila Catraca."}},
[97257] = {"Clamor do fogo", {"Espere Olariaan iniciar o ritual no Braseiro da Oferenda e siga as instruções dele.","","Você precisa levar a Chama Eterna a Valanaar antes que o tempo se esgote."}},
[97263] = {"Sua encomenda chegou", {"Entregue o pacote perdido de Eldrun."}},
[97265] = {"Ódio aos Furiódios", {"Derrote uma variedade de sátiros Furiódios em Sargeron, em Desolação, e depois fale novamente com Ara'kai na Aldeia Pescassombra."}},
[97275] = {"Por Uqueê a pressa?", {"Dê a Poção de Yelmak a Uqueê."}},
[97277] = {"Grund e Gozwin", {"Ache o acampamento de Grund e Gozwin nas colinas a noroeste. Recupere o Registro de Mecânico de Gozwin e mate o Leopardo da Neve Predador."}},
[97279] = {"Armas extraviadas", {"Colete 6 Armas de Treino Abandonadas e vá até Kzan Cortarrasga, no Covil."}},
[97281] = {"Uma tempestade se formando", {"Leve o Orbe da Tempestade Opaco para Rezlak perto do Barranco da Ravina Seca."}},
[97282] = {"Potencial trovejante", {"Leve 5 Órgãos de Lagarto Trovejante Carregados para Rezlak perto do Barranco da Ravina Seca."}},
[97284] = {"A vingança de Vahlarriel", {"Mate orcs Lâmina Ardente na Fortaleza Machado do Trovão, em Desolação, e então fale novamente com Vahlarriel Matademônios no Posto do Nijel."}},
[97286] = {"Acesso à pesquisa", nil},
[97287] = {"Negociações arguciosas", {"Fale com a Imagem da Arquimaga Modera nos arredores de Dalaran."}},
[97288] = {"Tormento sem fim", {"Entregue a Cabeça Abominável ao Mestre-boticário Faranello na Cidade Baixa."}},
[97289] = {"Tormento sem fim", {"Leve a Cabeça do Barão ao corpo de Othmar na Cidade Baixa."}},
[97290] = {"Tormento sem fim", {"Relate suas descobertas ao Mestre-boticário Faranello na Cidade Baixa."}},
[97291] = {"Tormento sem fim", {"Obtenha um Morrião Tóxico com Clorinda Grisette no Distrito Comercial, Pustulerva perto do local de Treinamento de Herborismo, e Essência da Agonia com o comerciante de venenos no Distrito dos Ladinos para entregar ao Mestre-boticário Faranello na Cidade Baixa."}},
[97292] = {"Tormento sem fim", {"Injete Soro Sibilante nos mecanismos sobre o corpo de Othmar para o Mestre-boticário Faranello."}},
[97326] = {"Pedra pra sentar", {"Leve 8 Pedregulhos Lisos para Thra atrás do Castelo Grommash."}},
[97328] = {"Algo de valor", {"Recupere 8 Carregamentos Roubados nas Ruínas de Zul'Kanda, na Selva do Espinhaço, e entregue a carga recuperada a alguém na Angra do Butim."}},
[97329] = {"Cadê a chave?", {"Obtenha a Chave Primitiva com os trolls das Ruínas de Zul'Kanda, na Selva do Espinhaço, e leve-a a Zimmix Cospefaísca."}},
[97331] = {"A grande fuga de Zimmix", {"Escolte Zimmix Cospefaísca para longe das Ruínas de Zul'Kanda. Depois, fale com o Mestre Portuário Lozgil, na Angra do Butim, sobre o resgate bem-sucedido."}},
[97332] = {"Confiando duas vezes em quem não merece", {"Entregue o Pacote Reprocessado Duas Vezes ao Mestre Portuário Carrapeto no Porto Detonapavio, nas Sendas do Rio."}},
[97453] = {"Passando a roçadeira", {"Mate 6 Ervas Carnívoras ao sul de Grom'gol e depois informe a mãe de Gemmil."}},
[97485] = {"Tradições do Penhasco", {"Compre um Maço de Ervas com Nida, a herborista, um Maço de Galhos de Cedro com Nata, a fornecedora de encantamento, Fio de Tendão com Mahu, o fornecedor de couraria, e Pederneira e Lenhas Cerimoniais com Naal, o fornecedor de culinária.","","Combine os itens e espalhe o incenso do Platô dos Caçadores."}},
[97530] = {"Deveres dos Dunamalho", {"O Chefe de Segurança Silvadágua do Porto de Bondebico, em Tanaris, quer que você um recupere bracelete particularmente brilhante que foi perdido próximo ao complexo ôgrico de Dunamalho."}},
[97536] = {"Lixo Gnômico", {"Jhordy Lapforge quer que você retorne até ele depois que você descartar o Caixote de Refugo Radioativo no deserto de Tanaris, a uma distância segura de Geringontzan e de outros lixos."}},
[97538] = {"Pigmento para tinta", {"Tah Casco Invernal, no Penhasco do Trovão, deseja 30 Vagens de Erva-turva do Lago Mirkfallon."}},
[97539] = {"Suturas de seda", {"Devolva 12 Sedaracnas Cirúrgicas ao Doutor Victor Zerbini na Ruína do Martelo, no Planalto Arathi."}},
[97558] = {"Pelegos para os Renegados", {"Leve 8 Membranas de Asa de Quiropúsculo, 6 Pelego de Cão das Trevas e 3 Pele de Murloc Pinavil para Lenita Ravais."}},
[97583] = {"SACOLEJO", {"Compre Lodo de Visgo Nutritivo e volte até o visgo empolgado com quem você fez amizade. Se ele parecer cansado, tente dançar com ele outra vez para chamar sua atenção."}},
[97617] = {"Verificações de segurança", {"Recupere 8 Artefatos Não Estudados, um Capacete de Mineração da Liga dos Exploradores e um Alvião Imaculado e leve tudo para Dorgaron, na fronteira entre Loch Modan e os Ermos."}},
[97891] = {"Entrega expressa de poções", {"Leve a Poção Instável ao Doutor Martinho Nunes, no Boticarium, dentro do tempo estipulado."}},
[97894] = {"Negócios em Auberdine", {"Veja como está Gorbold Manácero em Auberdine, na Costa Negra.","","Borgus mencionou um barco no cais mais ao sul do Porto de Ventobravo que pode levar você até lá."}},
