[97977] = {"O chamado da natureza", {"Colete 4 Totens Masca-pinho e leve-os a Tarindrella."}},
[97979] = {"A Deusa provê", {"Lance Luz de Eluna e Fusão Sombria."}},
[97985] = {"Corações trovejantes", {"Mate Coração da Tempestade, em Mil Agulhas, e obtenha o coração dele."}},
[98013] = {"Forças crescentes", {"Elimine 12 Mirmidões Escamarraio, 8 Feiticeiras Escamarraio e 6 Guerreiros Escamarraio para Arbal no Bosque dos Ancientes."}},
[98021] = {"Jornada ao Morro da Sentinela", {"Apresente-se a Miguel Mantoforte no Morro da Sentinela, em Cerro Oeste."}},
[98024] = {"Jornada para a Encruzilhada", {"Fale com Thork na Encruzilhada, que fica nos Sertões."}},
[98025] = {"PROCURA-SE: Jai'vhanel", {"Encontre e mate a coruja conhecida como Jai'vhanel e pegue uma das penas dela. A coruja preta foi vista pela última vez ao norte das ruínas de Ameth'Aran, perto da base da montanha. Relate a morte de Jai'vhanel à Sentinela Glynda Nal'Shea em Auberdine."}},
[98028] = {"Barão Marinous", {"Leve o Globo de Água Enevoado para Onu no Bosque dos Ancientes, na Costa Negra."}},
[98042] = {"É tudo muito divertido, até que...", {"Obtenha um Olho Sem Igual de um Discípulo ou Capanga do Crepúsculo na Glaive do Mestre, na Costa Negra, e encontre alguém em Auberdine que esteja disposto a ficar com ele."}},
[98046] = {"Coroa da Terra", {"Leve o Recipiente Drenado a Lariia no Templo da Lua, em Darnassus."}},
[98059] = {"O arsenal de Eira dos Montes", {"Deixe o Pedido da Companhia Selado que você recebeu na mesa de contabilidade da prefeitura de Eira dos Montes."}},
[98065] = {"Coroa da Terra", {"Leve os Restos do Poço Lunar para Tyrande Murmuréolo no Templo da Lua, em Darnassus."}},
[98067] = {"Olhos das sentinelas", {"Posicione Corujas Sentinelas na entrada das profundezas do Forte Cenariano, no Banco de Darnassus, na estalagem do Terraço dos Artesãos e no Portão da Cidade para a Sentinela Dália Gumélion no Templo da Lua, em Darnassus."}},
[98069] = {"Suprimentos de Vento Livre Roubados", {"Leve 8 Suprimentos de Vento Livre Roubados para Jandia, na Aldeia Vento Livre."}},
[98070] = {"Um fim para as guinchadoras", {"Mate 5 Harpias Guinchadoras, 5 harpias Plumerrantes Guinchadoras e 5 harpias Arautas do Vento Guinchadoras."}},
[98071] = {"O brique do cervejeiro", {"Entregue as garrafas de Varietal de Quedarroca em Dun Garok, no sudeste do Contraforte de Eira dos Montes, e traga de volta um saco do Lúpulo Artesanal deles."}},
[98072] = {"Croquinhos do céu", {"Colete 8 Escamas Carmesins Imaculadas e leve-as para Iago Halberque, no Porto de Menethil."}},
[98093] = {"Trabalho de campo", {"Sulhasa, na parte sul dos Sertões, quer que você elimine 7 Lagartos Borrascouro e 7 Espreitadores Presavaia na área para que ela possa descer da árvore com segurança."}},
[98094] = {"Suporte aos batedores", {"A Alta-executora Darthalia quer que você entregue as ordens atualizadas para o Sicário Masoj, ao sul da Serraria Tarren, nos arredores de Dun Garok."}},
[98095] = {"Vantagens valiosas", {"O Sicário Masoj precisa que você deixe as três Ampolas de Boticário nos picos ao redor do Contraforte de Eira dos Montes e depois retorne até ele."}},
[98189] = {"Devolva a estatueta", {"Leve a Estatueta de Menethil ao Capitão Punhoforte na Bastilha Menethil."}},
[98190] = {"Amigo da família", {"Leve a Estatueta de Menethil ao Grão-lorde Bolvar Fordragon na Bastilha Ventobravo."}},
[98191] = {"Amigo da família", {"Leve a Estatueta de Menethil ao Lorde Grayson Quebrassombra na Catedral da Luz."}},
[98197] = {"Espólios da guerra", {"Recupere 6 Madeiras Serradas de Khaz Modan e 30 Ferros de Khaz Modan no Porto de Menethil para Valstag Ferroqueixo."}},
[98208] = {"Flor dos céus", {"Recupere a Nord'el para Sylessa Murmussombra no Porto de Menethil."}},
[98209] = {"Flor dos céus", {"Leve a Nord'el a Trovejius Tecevento em Auberdine, na Costa Negra.","","Sylessa mencionou que um barco no Porto de Menethil pode levar você até lá."}},
[98216] = {"Entendendo nosso presente", {"Use a Pedra de Goaz perto do Guardião de Goaz e leve a Pedra-chave Titânica ao Prospector Whelgar."}},
[98219] = {"O tenente desonrado", {"Fale com o Tenente Fárrio Orinelle na Costa Sul, no Contraforte de Eira dos Montes."}},
[98221] = {"Das cinzas", {"O Capitão Punhoforte, na Bastilha Menethil, quer que você destrua os 4 conjuntos de Planos de Ataque no Acampamento Presirada."}},
[98223] = {"Velhos hábitos", {"Leve o Grimório Esfarrapado ao Capitão Punhoforte no Porto de Menethil."}},
